<?php defined('_JEXEC') or die; $job=is_array($workspace['job']??null)?$workspace['job']:null; ?>
<div class="dh-page-heading"><div><p class="dh-eyebrow">FROM EVIDENCE TO FILE</p><h1>Reports & exports</h1><p class="dh-lead">Download existing supported formats for a retained match.</p></div></div>
<?php if ($job): $jobId=(string)($job['id']??'');$jobStatus=(string)($job['status']??'unknown'); ?>
  <section class="dh-panel dh-export-job" aria-labelledby="dh-export-heading"><div class="dh-panel-heading"><h2 id="dh-export-heading">Export <?= $jobStatus === 'succeeded' ? 'ready' : 'status' ?></h2><span class="dh-badge"><?= $escape(ucfirst($jobStatus)) ?></span></div><p>State: <strong><?= $escape($jobStatus) ?></strong></p>
    <?php if ($jobStatus==='succeeded'): ?><p>Your file has been produced by the existing backend and is ready to download.</p><a class="dh-button dh-button-primary" href="<?= $escape($route(['task'=>'actions.download','job_id'=>$jobId])) ?>">Download report <span aria-hidden="true">↓</span></a>
    <?php elseif (in_array($jobStatus,['failed','cancelled','interrupted'],true)): ?><p class="dh-muted">This export did not complete. The retained source record remains available. Return to the match and request a new export when the service is ready.</p>
    <?php else: ?><p class="dh-muted">The backend is preparing the file. Refresh this job to check its actual status.</p><a class="dh-button dh-button-primary" href="<?= $escape($route(['section'=>'reports','job_id'=>$jobId]+($match?['match_id'=>$match['id']]:[]))) ?>">Refresh export status</a><?php endif; ?>
  </section>
<?php endif; ?>
<?php if ($match): ?>
  <section class="dh-panel"><p class="dh-eyebrow">SELECTED MATCH</p><h2><?= $escape($match['home']['name']??'Home') ?> — <?= $escape($match['away']['name']??'Away') ?></h2><p class="dh-muted"><?= $escape($date($match['event_date']??null)) ?> · <?= $escape($match['competition']??'') ?></p><p>Choose a format. Creating an export uses this retained record; it does not synchronize a provider or run a model.</p><?php $exportForm($match); ?><p class="dh-timestamp">Canonical ID <code><?= $escape($match['id']) ?></code></p><a href="<?= $escape($route(['section'=>'matches','match_id'=>$match['id']])) ?>">Return to match details <span aria-hidden="true">→</span></a></section>
<?php elseif (!$job): ?><section class="dh-panel"><h2>Choose the record to export</h2><p class="dh-muted">Open a retained match, then choose JSON, CSV or Excel from its Reports & exports page.</p><a class="dh-button dh-button-primary" href="<?= $escape($route(['section'=>'matches'])) ?>">Choose a match</a></section><?php endif; ?>
<aside class="dh-note"><div><h2>Your records stay protected</h2><p>Exports require an authorized Joomla session. Downloads are delivered through the existing server-side bridge; no backend credential is sent to your browser.</p></div></aside>
